insert into public.rotations (id, name, short, is_current, slots, note, field_id) values
('r-current', 'Boro – Fallow – T. Aman', 'Current', true, '[{"crop": "boro", "start": 1, "months": 5}, {"crop": "aman", "start": 7, "months": 4}]'::jsonb, 'What most farmers around Ashulia grow. Boro needs a lot of pumped water, and the land sits empty in June and December.', 'ashulia-demo'),
('r-awd', 'Boro (AWD) – Fallow – T. Aman', 'AWD', false, '[{"crop": "boro_awd", "start": 1, "months": 5}, {"crop": "aman", "start": 7, "months": 4}]'::jsonb, 'Same crops, but let the Boro field dry out for a few days between waterings (AWD). Saves about a quarter of the water.', 'ashulia-demo'),
('r-mustard-boro', 'Mustard – Late Boro – T. Aman', '3-crop', false, '[{"crop": "mustard", "start": 11, "months": 3}, {"crop": "late_boro", "start": 2, "months": 4}, {"crop": "aman", "start": 7, "months": 4}]'::jsonb, 'Adds a quick mustard crop before a later Boro. More income, but the Boro then flowers in hot April.', 'ashulia-demo'),
('r-mustard-mung', 'Mustard – Mungbean – T. Aman', 'Legume', false, '[{"crop": "mustard", "start": 11, "months": 3}, {"crop": "mungbean", "start": 3, "months": 3}, {"crop": "aman", "start": 7, "months": 4}]'::jsonb, 'Grows mustard and mungbean instead of Boro. Far less pumping, and mungbean feeds the soil for the next crop.', 'ashulia-demo'),
('r-maize-mung', 'Maize – Mungbean – T. Aman', 'Maize', false, '[{"crop": "maize", "start": 11, "months": 5}, {"crop": "mungbean", "start": 4, "months": 3}, {"crop": "aman", "start": 7, "months": 4}]'::jsonb, 'Winter maize instead of Boro: sells well and needs half the water. Mungbean after it feeds the soil.', 'ashulia-demo');
