insert into public.sources (id, name, product, doi, url, use, kind) values
('power', 'NASA POWER', 'Daily point API, community AG (T2M, T2M_MAX, T2M_MIN, PRECTOTCORR, RH2M, ALLSKY_SFC_SW_DWN, GWETTOP, GWETROOT)', null, 'https://power.larc.nasa.gov', '30-year weather, rainfall and soil wetness; crop water need (FAO-56 Hargreaves). Tmax bias-adjusted by month to NEX-GDDP-CMIP6 historical; the 2017 shift in rain and soil wetness is flagged and no trend is fitted across it', 'nasa'),
('modis', 'MODIS Terra MOD13Q1 v061', '16-day 250 m vegetation indices, via ORNL DAAC Land Product Subsets API', '10.5067/MODIS/MOD13Q1.061', 'https://modis.ornl.gov/data/modis_webservice.html', 'Greenness since 2000: seasons, crop condition', 'nasa'),
('cmip6', 'NASA NEX-GDDP-CMIP6', 'Bias-adjusted daily tasmax and pr, 0.25°, SSP2-4.5 and SSP5-8.5 (sampled years), AWS Open Data', '10.7917/OFSG3345', 'https://registry.opendata.aws/nex-gddp-cmip6/', 'Climate futures for the rotation comparison', 'nasa'),
('merra2', 'NASA GMAO MERRA-2 / GEOS-IT', 'Soil wetness served through POWER (GWETTOP, GWETROOT)', null, 'https://gmao.gsfc.nasa.gov/reanalysis/MERRA-2/', 'Root-zone soil wetness', 'nasa'),
('fao56', 'FAO Irrigation and Drainage Paper 56', 'Crop coefficients (Table 12), Hargreaves ET0 (eq. 52), effective rainfall', null, 'https://www.fao.org/4/x0490e/x0490e00.htm', 'Crop water need', 'method'),
('frg', 'Fertilizer Recommendation Guide 2018 (BARC)', 'Nutrient advice for Bangladesh crops', null, 'https://barc.gov.bd', 'General soil-nutrient guidance; doses depend on a soil test', 'method'),
('openmeteo', 'Open-Meteo forecast API (not NASA)', '7-day forecast from national weather models, fetched live', null, 'https://open-meteo.com', 'Next-7-days heavy rain and heat warnings only (CC-BY 4.0, non-commercial)', 'method'),
('esri', 'Esri World Imagery and OpenStreetMap', 'Map tiles for drawing the field', null, 'https://www.openstreetmap.org/copyright', 'Background map only (© Esri, Maxar; © OpenStreetMap contributors)', 'method'),
('drone', 'Furrow drone flights', 'RGB orthomosaic → canopy cover (5 m cells)', null, null, 'DEMO data in this build; replaced by our own flights', 'demo');
